// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testRegression_property() public {
        address owner = address(0x0);
        address logger = address(0x1);

        vm.startPrank(owner);
        c.setApprovedLogger(logger, true);
        vm.stopPrank();

        vm.prank(logger);
        bool result = c.logLiquidated();

        assertTrue(result);
    }
}
